package com.astrocare.controller; import com.astrocare.dto.*; import com.astrocare.service.TelemetryService; import lombok.RequiredArgsConstructor; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.core.Authentication; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/health") @RequiredArgsConstructor public class HealthController {private final TelemetryService service; @GetMapping("/latest/{astronautId}") public TelemetryResponse latest(@PathVariable Long astronautId,Authentication a){return service.latest(astronautId,a);} @GetMapping("/history/{astronautId}") public List<TelemetryResponse> history(@PathVariable Long astronautId,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime to,Authentication a){return service.history(astronautId,a,from==null?LocalDateTime.now().minusDays(1):from,to==null?LocalDateTime.now():to);}}
